function reviewMatePlusPeriodPanel(draft){
 const period=draft.period||{},progress=draft.snapshot?.progress||{},otj=draft.snapshot?.otj||{},criterion=COURSE.nvqUnits?'Learning Outcomes':'KSBs',previous=period.firstReview?'First recorded ReviewMate+ meeting':`Compared with ${formatShortDate(courseReviewMatePlusMeetings().find(item=>item.id===draft.previousMeetingId)?.date)}`,evidenceCount=(period.newEvidence||[]).reduce((sum,item)=>sum+Number(item.added||0),0);
 return `<section class="card panel reviewplus-period"><div class="reviewplus-section-head"><div><span>1</span><div><div class="number">AUTOMATIC REVIEW PERIOD</div><h3>Progress since the previous review</h3><p>${esc(previous)}</p></div></div></div><div class="reviewplus-stat-grid"><div><small>Progress gained</small><strong>+${Number(period.progressGain||0)}%</strong></div><div><small>New evidence</small><strong>${evidenceCount}</strong></div><div><small>New ${criterion}</small><strong>${Number(period.criterionGain||0)}</strong></div><div><small>Current progress</small><strong>${Number(progress.green||0)}%</strong></div></div><div class="reviewplus-auto-grid"><article><h4>New evidence completed</h4>${reviewMatePlusList(period.newEvidence,'No new evidence since the previous ReviewMate+ meeting.',item=>`<li><strong>${esc(assignmentCardCode({n:item.assignment}))}</strong> · ${esc(friendlyEvidenceSection(item.section))}${Number(item.added)>1?` × ${Number(item.added)}`:''}</li>`)}</article><article><h4>New ${criterion} completed</h4>${reviewMatePlusList(period.newCriteria,`No new ${criterion} completed in this review period.`,item=>`<li><strong>${esc(item.code)}</strong> · ${esc(item.summary)}</li>`)}</article></div><div class="reviewplus-current-line"><span>${learningHoursMateName()}: <strong>${Number(otj.total||0).toFixed(1)} / ${Number(otj.expected||0).toFixed(1)} hrs</strong></span><span>Assignments: <strong>${Number(progress.completed||0)} / ${Number(progress.total||0)}</strong></span><span>${criterion}: <strong>${Number(progress.ksbCompleted||0)} / ${Number(progress.ksbTotal||0)}</strong></span></div></section>`;
}
function reviewMatePlusVoiceField(key,id,value,label){return `<label class="field full reviewplus-voice-field"><span>${label}</span><div class="voice-text-field"><textarea class="input" id="${id}" data-reviewplus-field="${key}" data-voice-text-ready="1" rows="6" maxlength="700" placeholder="Speak or type the learner’s own reflection…">${esc(value||'')}</textarea><button type="button" class="voice-text-button no-print" data-reviewplus-voice="${key}" aria-label="Start voice to text" aria-pressed="false">${appIcon('microphone','voice-text-icon')}</button></div><small>Use the microphone to capture the learner’s own words, then edit the text if required.</small></label>`}
function reviewMatePlusSignatureField(draft,key,title,useProfile=false){const value=draft[key]||'';return `<section class="reviewplus-signature" data-reviewplus-signature="${key}"><h4>${esc(title)}</h4>${value?`<div class="saved-signature-wrap"><img class="sig-preview saved-signature-preview" src="${esc(value)}" alt="${esc(title)} saved"><span class="saved-signature-label">Signature saved securely on this device</span></div><div class="reviewplus-signature-actions"><button type="button" class="btn secondary compact" data-reviewplus-replace-signature="${key}">Replace</button><button type="button" class="link-button" data-reviewplus-clear-signature="${key}">Clear</button></div>`:`<canvas class="signature-pad reviewplus-signature-pad" data-reviewplus-signature-pad="${key}" aria-label="${esc(title)} signature box"></canvas><div class="reviewplus-signature-actions"><button type="button" class="btn secondary compact" data-reviewplus-save-signature="${key}">Save signature</button><button type="button" class="link-button" data-reviewplus-clear-pad="${key}">Clear box</button>${useProfile&&state.profile?.signature?`<button type="button" class="link-button" data-reviewplus-profile-signature="${key}">Use learner profile signature</button>`:''}</div>`}</section>`}
function reviewMatePlusPreviousTargetsPanel(draft){const rows=draft.previousTargets||[],done=rows.filter(item=>item.completed).length;return `<section class="card panel reviewplus-block"><div class="reviewplus-section-head"><div><span>2</span><div><div class="number">PREVIOUS TARGETS</div><h3>${rows.length?`${done} completed · ${rows.length-done} outstanding`:'No previous ReviewMate targets'}</h3></div></div></div><div class="reviewplus-previous-targets">${rows.length?rows.map(item=>`<article class="${item.completed?'complete':'outstanding'}"><b>${item.completed?'✓':'○'}</b><div><strong>Target ${item.sequence} · ${esc(item.title)}</strong><small>${item.completed?'Completed':`Outstanding · ${esc(item.progress||'In progress')}`}</small></div></article>`).join(''):'<p class="reviewplus-none">This is the learner’s first recorded target review.</p>'}</div></section>`}
function reviewMatePlusMeetingForm(draft){
 const period=draft.period||{},otj=draft.snapshot?.otj||{},epa=draft.snapshot?.epa,academy=period.newTests||[],slides=period.newSlides||[],attendance=Number(draft.attendance),attendanceTone=draft.attendance===''?'neutral':attendance>=85?'green':attendance>=75?'amber':'red';
 return `${reviewMatePlusPeriodPanel(draft)}${reviewMatePlusPreviousTargetsPanel(draft)}<section class="card panel reviewplus-block"><div class="reviewplus-section-head"><div><span>3</span><div><div class="number">REVIEW DETAILS</div><h3>Attendance, ${learningHoursShortLabel()}, Academy and EPA</h3></div></div></div><div class="form-grid reviewplus-details"><label class="field"><span>Review date</span><input class="input" type="date" data-reviewplus-field="date" value="${esc(draft.date)}"></label><label class="field"><span>Attendance at review</span><div class="reviewplus-attendance ${attendanceTone}"><input class="input" type="number" min="0" max="100" step="0.1" inputmode="decimal" data-reviewplus-field="attendance" value="${esc(draft.attendance)}" placeholder="e.g. 92"><b>%</b></div></label><label class="field"><span>Coach / reviewer</span><input class="input" data-reviewplus-field="reviewerName" value="${esc(draft.reviewerName)}" placeholder="Name of reviewer"></label><label class="field"><span>Employer representative</span><input class="input" data-reviewplus-field="employerRepresentative" value="${esc(draft.employerRepresentative)}" placeholder="Name of employer representative"></label><label class="field"><span>Employer role</span><input class="input" data-reviewplus-field="employerRole" value="${esc(draft.employerRole)}" placeholder="Job title or relationship to learner"></label><label class="field"><span>Next formal review</span><select class="input" data-reviewplus-field="intervalWeeks">${[8,10,12].map(weeks=>`<option value="${weeks}" ${Number(draft.intervalWeeks)===weeks?'selected':''}>${weeks} weeks</option>`).join('')}</select></label></div><div class="reviewplus-activity-grid"><article><h4>${learningHoursMateName()} compliance</h4><strong>${Number(otj.total||0).toFixed(1)} / ${Number(otj.expected||0).toFixed(1)} hrs</strong><p>${Number(otj.total||0)>=Number(otj.expected||0)?'At or above the expected position.':`${Math.max(0,Number(otj.expected||0)-Number(otj.total||0)).toFixed(1)} hours below the expected position.`}</p><small>${(period.newLearningHours||[]).length} new activit${(period.newLearningHours||[]).length===1?'y':'ies'} · ${Number(period.newLearningHoursTotal||0).toFixed(1)} hours this period</small></article><article><h4>Academy activity</h4><strong>${academy.length} new test${academy.length===1?'':'s'} · ${slides.length} slide pack${slides.length===1?'':'s'}</strong><p>${academy.length?academy.map(item=>`${item.title}: ${item.score}${item.grade?` ${item.grade}`:''}`).join(' · '):'No new Academy result in this review period.'}</p></article>${epa?`<article><h4>EPA readiness</h4><strong>${Number(epa.overall||0)}%</strong><p>Knowledge ${Number(epa.knowledge||0)}% · Discussion ${Number(epa.discussion||0)}% · Practical ${Number(epa.practical||0)}%</p></article>`:`<article><h4>Course route</h4><strong>Learning Outcome programme</strong><p>EPA readiness is not used for this course.</p></article>`}</div></section><section class="card panel reviewplus-block"><div class="reviewplus-section-head"><div><span>4</span><div><div class="number">MEETING DISCUSSION</div><h3>Reflection, employer voice and support</h3></div></div></div><div class="form-grid">${reviewMatePlusVoiceField('learnerReflection','reviewPlusLearnerReflection',draft.learnerReflection,'Learner reflection')}<label class="field full"><span>Employer comments</span><textarea class="input" data-reviewplus-field="employerComments" rows="6" maxlength="700" placeholder="Employer view of progress, workplace performance and development…">${esc(draft.employerComments)}</textarea></label><label class="field full"><span>Support or barriers discussed</span><textarea class="input" data-reviewplus-field="barriers" rows="4" maxlength="400" placeholder="Record any attendance, wellbeing, access, workplace or learning barriers discussed. Enter None discussed where appropriate.">${esc(draft.barriers)}</textarea></label><label class="field full"><span>Agreed support and actions</span><textarea class="input" data-reviewplus-field="supportActions" rows="4" maxlength="400" placeholder="Record support agreed, who will provide it and any follow-up action. Enter No additional support where appropriate.">${esc(draft.supportActions)}</textarea></label></div></section><section class="card panel reviewplus-block"><div class="reviewplus-section-head"><div><span>5</span><div><div class="number">NEXT REVIEW PERIOD</div><h3>Five new ReviewMate targets</h3><p>Each target is due one week after the previous target and repeats in the weekly reminder until completed.</p></div></div><button type="button" class="btn secondary" id="refreshReviewPlusTargets">Refresh targets</button></div><div class="reviewmate-target-list">${(draft.targets||[]).map((target,index)=>reviewTargetCard(target,index,true,draft.date)).join('')}</div><div class="form-grid reviewplus-reminders"><label class="field"><span>Weekly reminder day</span><select class="input" data-reviewplus-field="reminderWeekday">${REVIEWMATE_WEEKDAYS.map((day,index)=>`<option value="${index}" ${Number(draft.reminderWeekday)===index?'selected':''}>${day}</option>`).join('')}</select></label><div class="field"><span>Next review due</span><strong class="reviewplus-next-date">${formatShortDate(reviewAddWeeks(draft.date,draft.intervalWeeks))}</strong></div></div></section><section class="card panel reviewplus-block reviewplus-signing"><div class="reviewplus-section-head"><div><span>6</span><div><div class="number">AGREEMENT AND SIGN-OFF</div><h3>Learner and employer signatures</h3><p>Both signatures appear clearly on the professional A4 review PDF.</p></div></div></div><div class="reviewplus-signature-grid">${reviewMatePlusSignatureField(draft,'learnerSignature','Learner signature',true)}${reviewMatePlusSignatureField(draft,'employerSignature','Employer signature')}</div><div class="reviewplus-save-panel"><p>The completed meeting will be saved in dated ReviewMate+ history, the five targets will become live, and the signed PDF will download immediately.</p><div class="btn-row"><button type="button" class="btn secondary" id="cancelReviewPlusDraft">Save draft and close</button><button type="button" class="btn" id="saveReviewPlusMeeting">Complete review and download PDF</button></div></div></section>`;
}
function reviewMatePlusHistory(){const rows=courseReviewMatePlusMeetings();if(!rows.length)return '';return `<section class="reviewplus-history"><div class="section-heading"><div><div class="number">REVIEWMATE+ HISTORY</div><h3>Completed review meetings</h3></div></div>${rows.map(item=>{const period=item.period||{},completed=(item.previousTargets||[]).filter(target=>target.completed).length;return `<details class="card reviewplus-history-item"><summary><span><strong>${esc(formatShortDate(item.date))}</strong><small>${esc(item.employerRepresentative||'Employer')} · Attendance ${Number(item.attendance||0).toFixed(1)}%</small></span><b>+${Number(period.progressGain||0)}% · +${Number(period.criterionGain||0)} ${COURSE.nvqUnits?'LO':'KSB'}</b></summary><div><div class="reviewplus-history-metrics"><span>New evidence <strong>${(period.newEvidence||[]).reduce((sum,row)=>sum+Number(row.added||0),0)}</strong></span><span>Previous targets <strong>${completed}/${(item.previousTargets||[]).length||5}</strong></span><span>${learningHoursShortLabel()} added <strong>${Number(period.newLearningHoursTotal||0).toFixed(1)} hrs</strong></span><span>Next review <strong>${esc(formatShortDate(item.nextReviewDate))}</strong></span></div><p><strong>Learner reflection:</strong> ${esc(item.learnerReflection||'—')}</p><p><strong>Employer comments:</strong> ${esc(item.employerComments||'—')}</p><div class="btn-row"><button type="button" class="btn secondary" data-reviewplus-pdf="${item.id}">Download signed A4 PDF</button></div></div></details>`}).join('')}</section>`}
function bindReviewMatePlusSignaturePad(key){const canvas=document.querySelector(`[data-reviewplus-signature-pad="${key}"]`);if(!canvas)return;const ctx=canvas.getContext('2d'),ratio=window.devicePixelRatio||1;canvas.width=Math.max(1,canvas.clientWidth)*ratio;canvas.height=Math.max(1,canvas.clientHeight)*ratio;ctx.scale(ratio,ratio);ctx.strokeStyle='#0b2b23';ctx.lineWidth=2.4;ctx.lineCap='round';ctx.lineJoin='round';let drawing=false,changed=false;const point=event=>{const rect=canvas.getBoundingClientRect(),source=event.touches?.[0]||event;return {x:source.clientX-rect.left,y:source.clientY-rect.top}};const start=event=>{event.preventDefault();drawing=true;changed=true;const p=point(event);ctx.beginPath();ctx.moveTo(p.x,p.y)};const move=event=>{if(!drawing)return;event.preventDefault();const p=point(event);ctx.lineTo(p.x,p.y);ctx.stroke()};const end=event=>{if(!drawing)return;event.preventDefault();drawing=false};canvas.addEventListener('pointerdown',start);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);document.querySelector(`[data-reviewplus-clear-pad="${key}"]`)?.addEventListener('click',()=>{ctx.clearRect(0,0,canvas.clientWidth,canvas.clientHeight);changed=false});document.querySelector(`[data-reviewplus-save-signature="${key}"]`)?.addEventListener('click',async()=>{if(!changed)return toast('Add the signature in the box first');state.reviewMatePlusDraft[key]=canvas.toDataURL('image/png');await persistReviewMatePlusDraft();renderReviewMatePlus();toast('Signature saved')})}
async function createReviewMatePlusPdf(meeting){
 const W=1240,H=1754,M=54,G=18,usable=W-2*M,half=(usable-G)/2,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d'),period=meeting.period||{},snapshot=meeting.snapshot||{},progress=snapshot.progress||{},otj=snapshot.otj||{},criterion=COURSE.nvqUnits?'LO':'KSB',mate=learningHoursMateName();x.fillStyle='#f7faf7';x.fillRect(0,0,W,H);x.fillStyle='#06382c';x.fillRect(0,0,W,150);x.fillStyle='#79d22f';x.fillRect(0,0,14,H);x.fillStyle='#fff';x.font='900 34px Arial';x.fillText('APPRENTICE+ REVIEWMATE+',M,58);x.font='800 28px Arial';x.fillText('Progress Review Record',M,98);x.font='600 17px Arial';x.fillText(`${meeting.learner||'Learner'} · ${meeting.courseName||COURSE.name}`,M,128);x.textAlign='right';x.font='700 18px Arial';x.fillText(formatShortDate(meeting.date),W-M,61);x.font='500 15px Arial';x.fillText(`Next review ${formatShortDate(meeting.nextReviewDate)}`,W-M,92);x.fillText(`Apprentice+ ${APP_VERSION}`,W-M,121);x.textAlign='left';
 const rounded=(px,py,pw,ph,fill,stroke='#dce7df')=>{x.fillStyle=fill;x.strokeStyle=stroke;x.lineWidth=1.5;x.beginPath();x.roundRect(px,py,pw,ph,14);x.fill();x.stroke()};
 const fitted=(text,px,py,pw,ph,max=15,min=10,colour='#263b3b',weight=400)=>{let font=max,lines=[];for(;font>=min;font--){lines=wrapPdfText(x,String(text||'—'),pw,`${weight} ${font}px Arial`);if(lines.length*(font+5)<=ph)break}x.fillStyle=colour;x.font=`${weight} ${font}px Arial`;const limit=Math.max(1,Math.floor(ph/(font+5)));lines.slice(0,limit).forEach((line,index)=>x.fillText(index===limit-1&&lines.length>limit?`${line.replace(/[ .]+$/,'')}…`:line,px,py+font+index*(font+5)));};
 const box=(title,text,px,py,pw,ph,fill='#fff')=>{rounded(px,py,pw,ph,fill);x.fillStyle='#0f766e';x.font='800 13px Arial';x.fillText(title.toUpperCase(),px+15,py+24);fitted(text,px+15,py+34,pw-30,ph-44,14,10,'#263b3b',400)};
 const metrics=[['PROGRESS',`+${Number(period.progressGain||0)}%`],['NEW EVIDENCE',String((period.newEvidence||[]).reduce((sum,row)=>sum+Number(row.added||0),0))],[`NEW ${criterion}S`,String(Number(period.criterionGain||0))],['ATTENDANCE',`${Number(meeting.attendance||0).toFixed(1)}%`]];metrics.forEach(([label,value],index)=>{const w=(usable-G*3)/4,px=M+index*(w+G);rounded(px,166,w,82,'#fff');x.fillStyle='#617169';x.font='800 12px Arial';x.fillText(label,px+14,190);x.fillStyle='#06382c';x.font='900 25px Arial';x.fillText(value,px+14,226)});
 const evidenceText=`Progress: ${Number(progress.green||0)-Number(period.progressGain||0)}% to ${Number(progress.green||0)}% (+${Number(period.progressGain||0)}%). Assignments: ${Number(progress.completed||0)}/${Number(progress.total||0)}. New evidence: ${(period.newEvidence||[]).length?(period.newEvidence||[]).map(item=>`${COURSE.nvqUnits?'EP':'AS'}${item.assignment} ${friendlyEvidenceSection(item.section)}${Number(item.added)>1?` x${item.added}`:''}`).join('; '):'None recorded'}. New ${criterion}s: ${(period.newCriteria||[]).length?(period.newCriteria||[]).map(item=>item.code).join(', '):'None recorded'}.`;
 const previousText=(meeting.previousTargets||[]).length?(meeting.previousTargets||[]).map(item=>`${item.completed?'Completed':'Outstanding'} - Target ${item.sequence}: ${item.title}`).join('\n'):'No previous ReviewMate targets were recorded.';box('Progress and completed evidence',evidenceText,M,266,half,186,'#f6fbf2');box('Previous targets',previousText,M+half+G,266,half,186,'#fffaf0');
 const academy=(period.newTests||[]).length?(period.newTests||[]).map(item=>`${item.title}: ${item.score}${item.grade?` ${item.grade}`:''}`).join('; '):'No new Academy tests';const epa=snapshot.epa?`EPA ${Number(snapshot.epa.overall||0)}% (Knowledge ${Number(snapshot.epa.knowledge||0)}%, Discussion ${Number(snapshot.epa.discussion||0)}%, Practical ${Number(snapshot.epa.practical||0)}%)`:'EPA readiness not used for this programme';box(`${mate}, Academy and EPA`,`${mate}: ${Number(otj.total||0).toFixed(1)} / ${Number(otj.expected||0).toFixed(1)} hrs; ${Number(period.newLearningHoursTotal||0).toFixed(1)} new hours across ${(period.newLearningHours||[]).length} activities. Academy: ${academy}. Knowledge Slides completed: ${(period.newSlides||[]).length}. ${epa}.`,M,470,usable,126,'#f1faf8');
 box('Learner reflection',meeting.learnerReflection,M,614,half,210);box('Employer comments',meeting.employerComments,M+half+G,614,half,210);box('Support or barriers discussed',meeting.barriers||'None discussed',M,842,half,154,'#fffaf0');box('Agreed support and actions',meeting.supportActions||'No additional support agreed',M+half+G,842,half,154,'#f6fbf2');
 const targetText=(meeting.targets||[]).map((target,index)=>`${index+1}. ${target.title} - due ${formatShortDate(target.dueDate)}. ${target.details}`).join('\n');box('Five new ReviewMate targets',targetText,M,1014,usable,286,'#fff');
 const signatureBox=async(title,name,data,px)=>{rounded(px,1318,half,334,'#fff');x.fillStyle='#0f766e';x.font='800 13px Arial';x.fillText(title.toUpperCase(),px+15,1342);x.fillStyle='#263b3b';x.font='700 17px Arial';x.fillText(name||'Name not recorded',px+15,1373);x.strokeStyle='#cbd8cf';x.strokeRect(px+15,1392,half-30,174);if(data){try{const image=await loadAppImage(data),scale=Math.min((half-58)/image.width,146/image.height);x.drawImage(image,px+29,1406,image.width*scale,image.height*scale)}catch{}}x.fillStyle='#617169';x.font='500 13px Arial';x.fillText(`Signed ${formatShortDate(meeting.date)}`,px+15,1596)};await signatureBox('Learner signature',meeting.learner,meeting.learnerSignature,M);await signatureBox('Employer signature',[meeting.employerRepresentative,meeting.employerRole].filter(Boolean).join(' · '),meeting.employerSignature,M+half+G);x.fillStyle='#06382c';x.fillRect(0,H-62,W,62);x.fillStyle='#fff';x.font='600 14px Arial';x.fillText('Apprentice+ · ReviewMate+ complete progress review',M,H-25);x.textAlign='right';x.fillText('Signed review record · Page 1 of 1',W-M,H-25);return makeImagePDF([dataUrlBytes(c.toDataURL('image/jpeg',.94))],W,H);
}
async function downloadReviewMatePlusPdf(meeting){try{const bytes=await createReviewMatePlusPdf(meeting),safe=String(meeting.learner||'Learner').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,''),name=`${safe||'Learner'}-ReviewMatePlus-${meeting.date}.pdf`;await downloadBlob(bytes,'application/pdf',name);analyticsEvent('reviewmate_plus_pdf_downloaded',{course:COURSE.id});toast('Signed ReviewMate+ PDF downloaded')}catch(error){console.error('ReviewMate+ PDF failed',error);toast('The ReviewMate+ PDF could not be created')}}
async function saveReviewMatePlusMeeting(){
 const draft=state.reviewMatePlusDraft;if(!draft)return;const attendance=Number(draft.attendance);if(!draft.date)return toast('Choose the review date');if(!Number.isFinite(attendance)||attendance<0||attendance>100)return toast('Enter attendance between 0 and 100%');if(!String(draft.learnerReflection||'').trim())return toast('Add the learner reflection');if(!String(draft.employerRepresentative||'').trim()||!String(draft.employerComments||'').trim())return toast('Add the employer representative and comments');if(!draft.learnerSignature||!draft.employerSignature)return toast('Both the learner and employer must sign the review');if((draft.targets||[]).length!==5)return toast('ReviewMate+ needs five new targets');
 const now=new Date().toISOString(),portfolioSnapshot=portfolioEvidenceSnapshot(),previousMeeting=courseReviewMatePlusMeetings().find(item=>item.id===draft.previousMeetingId)||null,targetReviewId=uid(),targets=scheduleReviewMateTargets(draft.targets,draft.date).map(target=>({...target,id:target.id||uid(),completed:false,manualComplete:false,reset:false})),review={id:targetReviewId,status:'active',courseId:COURSE.id,courseName:COURSE.name,learner:state.profile?.fullName||'Learner',date:draft.date,createdAt:now,updatedAt:now,reminderWeekday:Number(draft.reminderWeekday),intervalWeeks:Number(draft.intervalWeeks),nextReviewDate:reviewAddWeeks(draft.date,draft.intervalWeeks),snapshot:reviewMateSnapshot(),targets},history=retireCourseReviewMateReviews(reviewMateReviews(),targetReviewId,now);await saveReviewMateReviews([review,...history]);const meeting={...draft,status:'completed',savedAt:now,updatedAt:now,targetReviewId,attendance,targets,nextReviewDate:review.nextReviewDate,snapshot:review.snapshot,portfolioSnapshot,period:reviewMatePlusDelta(previousMeeting?.portfolioSnapshot||null,portfolioSnapshot)};delete state.data[reviewMatePlusDraftKey()];await saveReviewMatePlusMeetings([meeting,...reviewMatePlusMeetings()]);syncReviewMateReminders(review);state.reviewMatePlusDraft=null;state.reviewMateTab='plus';renderReviewMatePlus();analyticsEvent('reviewmate_plus_review_saved',{course:COURSE.id,target_count:5,attendance,interval_weeks:Number(draft.intervalWeeks)});await downloadReviewMatePlusPdf(meeting);
}
function bindReviewMatePlusDraft(){
 const draft=state.reviewMatePlusDraft;document.querySelectorAll('[data-reviewplus-field]').forEach(field=>{const update=()=>{const key=field.dataset.reviewplusField,value=field.type==='number'||field.tagName==='SELECT'&&['intervalWeeks','reminderWeekday'].includes(key)?field.value:String(field.value||'');draft[key]=value;if(key==='date')draft.targets=scheduleReviewMateTargets(draft.targets,value||isoToday())};field.oninput=update;field.onchange=async()=>{update();await persistReviewMatePlusDraft();if(['date','intervalWeeks'].includes(field.dataset.reviewplusField))renderReviewMatePlus()}});document.querySelectorAll('[data-reviewplus-voice]').forEach(button=>button.onclick=event=>{event.preventDefault();const target=document.querySelector(`[data-reviewplus-field="${button.dataset.reviewplusVoice}"]`);if(target)beginVoiceToText(target,button)});for(const key of ['learnerSignature','employerSignature'])bindReviewMatePlusSignaturePad(key);document.querySelectorAll('[data-reviewplus-replace-signature],[data-reviewplus-clear-signature]').forEach(button=>button.onclick=async()=>{const key=button.dataset.reviewplusReplaceSignature||button.dataset.reviewplusClearSignature;draft[key]='';await persistReviewMatePlusDraft();renderReviewMatePlus()});document.querySelectorAll('[data-reviewplus-profile-signature]').forEach(button=>button.onclick=async()=>{draft[button.dataset.reviewplusProfileSignature]=state.profile?.signature||'';await persistReviewMatePlusDraft();renderReviewMatePlus();toast('Learner profile signature added')});document.getElementById('refreshReviewPlusTargets')?.addEventListener('click',async()=>{draft.targets=reviewMatePlusFiveTargets(draft.date);await persistReviewMatePlusDraft();renderReviewMatePlus();toast('Five targets refreshed from live progress')});document.getElementById('cancelReviewPlusDraft')?.addEventListener('click',async()=>{await persistReviewMatePlusDraft();state.reviewMatePlusDraft=null;renderReviewMatePlus();toast('ReviewMate+ draft saved')});document.getElementById('saveReviewPlusMeeting')?.addEventListener('click',saveReviewMatePlusMeeting);
}
function renderReviewMatePlus(){
 let draft=state.reviewMatePlusDraft;if(!draft){const saved=state.data[reviewMatePlusDraftKey()];if(saved?.courseId===COURSE.id)draft=state.reviewMatePlusDraft=saved}const rows=courseReviewMatePlusMeetings(),body=draft?reviewMatePlusMeetingForm(draft):`<section class="card panel reviewmate-empty reviewplus-empty"><div class="reviewmate-empty-icon">${appIcon('revision')}</div><h2>${rows.length?'Start the next complete progress review':'Conduct the first complete progress review'}</h2><p>ReviewMate+ gathers live progress, evidence, ${COURSE.nvqUnits?'Learning Outcomes':'KSBs'}, ${learningHoursShortLabel()}, Academy and EPA activity, then records the review discussion, two signatures and five new targets.</p><button class="btn" id="startReviewMatePlus">${state.data[reviewMatePlusDraftKey()]?'Resume review meeting':'+ Start review meeting'}</button></section>`;app.innerHTML=shell(`<button class="back no-print" id="backReviewMate">← Toolbox</button><div class="section-heading reviewmate-heading"><div><div class="number">Productivity</div><h2>ReviewMate</h2><p class="muted">Live targets and complete signed progress-review meetings.</p></div></div>${reviewMateTabs()}${reviewMateProgressPanel()}${body}${reviewMatePlusHistory()}`);bindReviewMateTabs();document.getElementById('backReviewMate').onclick=()=>{state.reviewMateDraft=null;state.reviewMatePlusDraft=null;state.view='resources';render()};document.getElementById('startReviewMatePlus')?.addEventListener('click',async()=>{state.reviewMatePlusDraft=state.data[reviewMatePlusDraftKey()]||createReviewMatePlusDraft();await persistReviewMatePlusDraft();renderReviewMatePlus()});document.querySelectorAll('[data-reviewplus-pdf]').forEach(button=>button.onclick=()=>{const meeting=rows.find(item=>item.id===button.dataset.reviewplusPdf);if(meeting)downloadReviewMatePlusPdf(meeting)});if(draft)bindReviewMatePlusDraft();
}
function renderReviewMate(){
 if((state.reviewMateTab||'targets')==='plus'){renderReviewMatePlus();return}
 const reviews=courseReviewMateReviews(),latest=activeCourseReviewMateReview();if(latest)refreshReviewMateReview(latest);const draft=state.reviewMateDraft;if(draft)draft.targets=scheduleReviewMateTargets(draft.targets,draft.date);
 let body='';
 if(draft){body=`<section class="card panel reviewmate-setup"><div class="reviewmate-setup-head"><div><div class="number">NEW PROGRESS REVIEW</div><h3>Five targets based on live progress</h3><p>All five targets are set on this review date. Target 1 is due in one week, Target 2 in two weeks, through to Target 5 in five weeks.</p></div><button class="btn secondary" id="refreshReviewTargets">Refresh suggestions</button></div><div class="reviewmate-reminder-rule"><strong>Weekly reminder rule</strong><span>Every incomplete target is included each week. Completed targets are removed from the next reminder, and anything still outstanding remains until the next 8, 10 or 12-week review is saved.</span></div><div class="form-grid reviewmate-settings"><label class="field"><span>Review date</span><input class="input" type="date" id="reviewMateDate" value="${esc(draft.date)}"></label><label class="field"><span>Remind me every</span><select class="input" id="reviewMateWeekday">${REVIEWMATE_WEEKDAYS.map((day,index)=>`<option value="${index}" ${Number(draft.reminderWeekday)===index?'selected':''}>${day}</option>`).join('')}</select></label><label class="field"><span>Reset targets with next review in</span><select class="input" id="reviewMateInterval">${[8,10,12].map(weeks=>`<option value="${weeks}" ${Number(draft.intervalWeeks)===weeks?'selected':''}>${weeks} weeks</option>`).join('')}</select></label></div><div class="reviewmate-target-list">${draft.targets.map((target,index)=>reviewTargetCard(target,index,true,draft.date)).join('')}</div><div class="btn-row"><button class="btn secondary" id="cancelReviewMateDraft">Cancel</button><button class="btn" id="saveReviewMate">Save review and reminders</button></div></section>`}
 else if(latest){const complete=(latest.targets||[]).filter(reviewTargetComplete).length;body=`<section class="reviewmate-current-head"><div><div class="number">REVIEW SAVED ${esc(formatShortDate(latest.date))}</div><h2>${complete} of 5 targets completed</h2><p>Every incomplete target is repeated in the ${esc(REVIEWMATE_WEEKDAYS[latest.reminderWeekday]||'Monday')} reminder. Completed targets drop out; outstanding targets continue until the next review is saved on or around ${esc(formatShortDate(latest.nextReviewDate))}.</p></div><button class="btn" id="newReviewMate">+ New review</button></section><div class="reviewmate-target-list">${(latest.targets||[]).map((target,index)=>reviewTargetCard(target,index,false,latest.date)).join('')}</div>`}
 else body=`<section class="card panel reviewmate-empty"><div class="reviewmate-empty-icon">${appIcon('revision')}</div><h2>Create the first progress review</h2><p>ReviewMate will read the learner’s current evidence and statistics, then propose exactly five actionable targets with direct Go links and weekly reminders.</p><button class="btn" id="startReviewMate">Generate five targets</button></section>`;
 const history=reviews.length?`<section class="reviewmate-history"><div class="section-heading"><div><div class="number">REVIEW HISTORY</div><h3>Dated reviews</h3></div></div>${reviews.map(review=>{const complete=(review.targets||[]).filter(reviewTargetComplete).length,reset=review.status==='reset';return `<details class="card reviewmate-history-item ${reset?'reset':''}"><summary><span><strong>${esc(formatShortDate(review.date))}</strong><small>${esc(review.courseName||COURSE.name)}</small></span><b>${complete}/5 completed${reset?' · reset':''}</b></summary><div>${reviewMateHistoryStats(review)}${(review.targets||[]).map(target=>{const done=reviewTargetComplete(target),retired=!done&&target.reset;return `<p class="${done?'done':retired?'reset':''}"><span>${done?'✓':retired?'↺':'○'}</span>${esc(target.title)}${retired?' · reset at next review':''}</p>`}).join('')}</div></details>`}).join('')}</section>`:'';
 app.innerHTML=shell(`<button class="back no-print" id="backReviewMate">← Toolbox</button><div class="section-heading reviewmate-heading"><div><div class="number">Productivity</div><h2>ReviewMate</h2><p class="muted">Live targets and complete signed progress-review meetings.</p></div></div>${reviewMateTabs()}${reviewMateProgressPanel()}${body}${history}`);bindReviewMateTabs();
 document.getElementById('backReviewMate').onclick=()=>{state.reviewMateDraft=null;state.reviewMatePlusDraft=null;state.view='resources';render()};
 const start=document.getElementById('startReviewMate'),newReview=document.getElementById('newReviewMate');const makeDraft=()=>{const date=isoToday();state.reviewMateDraft={id:uid(),date,reminderWeekday:1,intervalWeeks:8,targets:scheduleReviewMateTargets(buildReviewMateTargets(),date)};renderReviewMate()};if(start)start.onclick=makeDraft;if(newReview)newReview.onclick=makeDraft;
 const reviewDate=document.getElementById('reviewMateDate');if(reviewDate)reviewDate.onchange=()=>{if(!reviewDate.value)return;state.reviewMateDraft.date=reviewDate.value;state.reviewMateDraft.targets=scheduleReviewMateTargets(state.reviewMateDraft.targets,reviewDate.value);renderReviewMate()};
 const refresh=document.getElementById('refreshReviewTargets');if(refresh)refresh.onclick=()=>{state.reviewMateDraft.targets=scheduleReviewMateTargets(buildReviewMateTargets(),state.reviewMateDraft.date);renderReviewMate();toast('Targets refreshed from live progress')};
 const cancel=document.getElementById('cancelReviewMateDraft');if(cancel)cancel.onclick=()=>{state.reviewMateDraft=null;renderReviewMate()};
 const save=document.getElementById('saveReviewMate');if(save)save.onclick=async()=>{const date=document.getElementById('reviewMateDate').value,reminderWeekday=Number(document.getElementById('reviewMateWeekday').value),intervalWeeks=Number(document.getElementById('reviewMateInterval').value);if(!date)return toast('Choose the review date');if(state.reviewMateDraft.targets.length!==5)return toast('ReviewMate needs five targets');const id=uid(),now=new Date().toISOString(),review={id,status:'active',courseId:COURSE.id,courseName:COURSE.name,learner:state.profile?.fullName||'Learner',date,createdAt:now,updatedAt:now,reminderWeekday,intervalWeeks,nextReviewDate:reviewAddWeeks(date,intervalWeeks),snapshot:reviewMateSnapshot(),targets:scheduleReviewMateTargets(state.reviewMateDraft.targets,date).map(target=>({...target,id:uid(),completed:false,manualComplete:false,reset:false}))},history=retireCourseReviewMateReviews(reviewMateReviews(),id,now);await saveReviewMateReviews([review,...history]);syncReviewMateReminders(review);state.reviewMateDraft=null;renderReviewMate();analyticsEvent('reviewmate_review_saved',{course:COURSE.id,target_count:5,interval_weeks:intervalWeeks});toast('Review saved · five weekly target reminders are active')};
 document.querySelectorAll('[data-review-go]').forEach(button=>button.onclick=()=>{const target=latest?.targets?.find(item=>item.id===button.dataset.reviewGo);if(target)openReviewMateTarget(target)});
 document.querySelectorAll('[data-review-complete]').forEach(button=>button.onclick=async()=>{const target=latest?.targets?.find(item=>item.id===button.dataset.reviewComplete);if(!target)return;const complete=reviewTargetComplete(target);if(complete&&reviewTargetAutoComplete(target))return toast('This target is completed by live learner progress');target.manualComplete=!complete;target.completed=target.manualComplete;target.completedAt=target.manualComplete?new Date().toISOString():null;target.completionMethod=target.manualComplete?'Marked complete in ReviewMate':'';latest.updatedAt=new Date().toISOString();await saveReviewMateReviews(reviewMateReviews().map(item=>item.id===latest.id?latest:item));syncReviewMateReminders(latest);renderReviewMate();toast(target.manualComplete?'Target completed':'Target reopened')});
}
function renderRemindMate(){const tab=state.remindMateTab||'home',items=reminders(),edit=items.find(x=>x.id===state.editingReminderId)||reminderDefaults();let body;if(tab==='entry')body=`<section class="card panel"><h3>${state.editingReminderId?'Edit reminder':'New reminder'}</h3><div class="form-grid"><div class="field full"><label>Reminder title</label><input class="input" id="reminderTitle" value="${esc(edit.title)}" placeholder="Complete review target"></div><div class="field full"><label>Reminder details</label><textarea class="input" id="reminderDetails" rows="5" placeholder="Add exactly what needs to be completed…">${esc(edit.details)}</textarea></div><div class="field"><label>Due date</label><input class="input" id="reminderDue" type="date" value="${esc(edit.due)}"></div><div class="field"><label>Repeat</label><select class="input" id="reminderRecurrence">${Object.entries(REMINDER_RECURRENCES).map(([id,label])=>`<option value="${id}" ${edit.recurrence===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Category</label><select class="input" id="reminderCategory">${['Review target','Assignment',learningHoursShortLabel(),'EPA','College','Employer','Personal','Other'].map(x=>`<option ${edit.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select class="input" id="reminderPriority">${['Low','Normal','High'].map(x=>`<option ${edit.priority===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="btn-row"><button class="btn secondary" id="cancelReminder">Cancel</button><button class="btn" id="saveReminder">Save reminder</button></div></section>`;else body=`<section class="reminder-groups">${[['overdue','Overdue'],['today','Due today'],['upcoming','Upcoming'],['completed','Completed']].map(([key,label])=>{const group=items.filter(r=>reminderStatus(r)===key);return `<section class="card panel reminder-group ${key}"><h3>${label} <span>${group.length}</span></h3><div class="reminder-list">${group.length?group.map(r=>`<article class="reminder-item"><button class="reminder-check ${r.completed?'checked':''}" data-toggle-reminder="${r.id}" aria-label="${r.completed?'Mark incomplete':r.recurrence!=='none'?'Complete and schedule next reminder':'Mark complete'}">${r.completed?'✓':''}</button><div><strong>${esc(r.title)}</strong><p>${esc(r.details)}</p><small>${formatShortDate(r.due)} · ${esc(r.category)} · ${esc(r.priority)}${r.recurrence!=='none'?` · <span class="reminder-repeat">↻ ${esc(REMINDER_RECURRENCES[r.recurrence])}</span>`:''}</small></div><button class="icon-button" data-edit-reminder="${r.id}">✎</button><button class="icon-button danger" data-delete-reminder="${r.id}">×</button></article>`).join(''):'<div class="empty-state compact">None</div>'}</div></section>`}).join('')}</section>`;app.innerHTML=shell(`<button class="back no-print" id="backReminder">← Toolbox</button><div class="section-heading"><div><div class="number">Toolbox</div><h2>RemindMate</h2><p class="muted">Turn review targets and important tasks into dated or recurring Apprentice+ reminders.</p></div><button class="btn" id="newReminder">+ New reminder</button></div>${body}`);bindRemindMate(tab)}
function bindRemindMate(tab){
 document.getElementById('backReminder').onclick=()=>{state.view='resources';render()};
 document.getElementById('newReminder').onclick=()=>{state.editingReminderId=null;state.remindMateTab='entry';render()};
 const byId=new Map(reminders().map(item=>[item.id,item]));
 document.querySelectorAll('.reminder-item').forEach(article=>{const id=article.querySelector('[data-toggle-reminder]')?.dataset.toggleReminder,item=byId.get(id),copy=article.children[1];if(!item?.reviewMate||!copy)return;const button=document.createElement('button');button.type='button';button.className='review-reminder-go';button.textContent=item.targetId?'Go to target →':'Open ReviewMate →';button.onclick=()=>openReviewMateReminder(item);copy.appendChild(button)});
 document.querySelectorAll('[data-edit-reminder]').forEach(b=>b.onclick=()=>{state.editingReminderId=b.dataset.editReminder;state.remindMateTab='entry';render()});
 document.querySelectorAll('[data-delete-reminder]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this reminder?'))return;saveReminders(reminders().filter(x=>x.id!==b.dataset.deleteReminder));render();toast('Reminder deleted')});
 document.querySelectorAll('[data-toggle-reminder]').forEach(b=>b.onclick=()=>{let nextDue='';saveReminders(reminders().map(x=>{if(x.id!==b.dataset.toggleReminder)return x;if(!x.completed&&x.recurrence!=='none'){nextDue=nextRecurringReminderDate(x);return {...x,due:nextDue,completed:false,lastCompletedAt:new Date().toISOString(),occurrenceCount:Number(x.occurrenceCount||0)+1}}return {...x,completed:!x.completed,completedAt:!x.completed?new Date().toISOString():null}}));render();toast(nextDue?`Completed · next reminder ${formatShortDate(nextDue)}`:'Reminder updated')});
 if(tab!=='entry')return;
 document.getElementById('cancelReminder').onclick=()=>{state.remindMateTab='home';render()};
 document.getElementById('saveReminder').onclick=()=>{const title=document.getElementById('reminderTitle').value.trim(),details=document.getElementById('reminderDetails').value.trim(),due=document.getElementById('reminderDue').value;if(!title||!details||!due)return toast('Add a title, details and due date');let arr=reminders(),existing=arr.find(x=>x.id===state.editingReminderId),item={...(existing||reminderDefaults()),title,details,due,recurrence:document.getElementById('reminderRecurrence').value,category:document.getElementById('reminderCategory').value,priority:document.getElementById('reminderPriority').value,updated:new Date().toISOString()};arr=existing?arr.map(x=>x.id===existing.id?item:x):[...arr,item];saveReminders(arr);state.editingReminderId=null;state.remindMateTab='home';render();toast('Reminder saved')};
}
function reminderNotificationId(r){return `reminder-${r.id}-${r.due}`}
function notificationPermissionStatus(){if(!('Notification'in window))return 'unsupported';return Notification.permission}
async function requestDeviceNotificationPermission(){if(!('Notification'in window))return toast('Device notifications are not supported by this browser');const permission=await Notification.requestPermission();renderSettings();if(permission==='granted'){refreshAppNotifications();toast('Device notifications enabled')}else toast(permission==='denied'?'Device notifications are blocked in browser settings':'Device notifications were not enabled')}
let reminderDeviceNotificationSyncing=false;
async function showDueReminderDeviceNotifications(due){if(reminderDeviceNotificationSyncing||notificationPermissionStatus()!=='granted'||!due.length)return;reminderDeviceNotificationSyncing=true;try{let sent=safeLocalObject('apprenticeplus.reminders.notified.v1'),changed=false;for(const r of due){const key=reminderNotificationId(r);if(sent[key])continue;const title=r.due<isoToday()?'Overdue Apprentice+ reminder':'Apprentice+ reminder due today',options={body:`${r.title}${r.details?` · ${r.details}`:''}`,tag:key,renotify:false,icon:'icon-192.png',badge:'icon-192.png',data:{type:'remindmate'}};try{if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.ready;await registration.showNotification(title,options)}else new Notification(title,options);sent[key]=new Date().toISOString();changed=true}catch(error){console.warn('Unable to show device reminder notification',error)}}if(changed){const activeKeys=new Set(reminders().map(reminderNotificationId));sent=Object.fromEntries(Object.entries(sent).filter(([key])=>activeKeys.has(key)));localStorage.setItem('apprenticeplus.reminders.notified.v1',JSON.stringify(sent))}}finally{reminderDeviceNotificationSyncing=false}}
function liveAppNotificationRecords(settings){const records=[];if(!settings.enabled)return records;if(settings.assignments){const ready=courseAssignments().filter(a=>assignmentComplete(a.n)&&!packUploaded(a.n));if(ready.length)records.push({id:`assignments-ready-${COURSE.id}-${ready.map(a=>a.n).join('-')}`,icon:'✓',title:`${ready.length} evidence pack${ready.length===1?' is':'s are'} ready`,body:`${ready.map(a=>assignmentCardCode(a)).join(', ')} can be downloaded or marked as uploaded.`,target:'assignment',value:String(ready[0].n),action:'Open evidence pack'})}if(settings.reviews){const progress=courseProgressStats();if(progress.tone==='behind')records.push({id:`progress-behind-${COURSE.id}`,icon:'↗',title:'Learner progress is behind target',body:`${progress.ksbCompleted} of ${progress.ksbTotal} ${COURSE.nvqUnits?'learning outcomes':'KSBs'} are complete. Open the progress scales for today’s position.`,target:'progress',action:'View progress'})}if(settings.otj){const exported=portfolioBuildingExportMap(),pending=otjEntries().filter(e=>!e.exportedAt).length+portfolioBuildingOtjEntries().filter(e=>!exported[e.id]).length,short=learningHoursShortLabel(),mate=learningHoursMateName();if(pending)records.push({id:`otj-ready-${COURSE.id}-${pending}`,icon:'⏱',title:`${short} entries ready to export`,body:`${pending} new manual or Portfolio building entr${pending===1?'y':'ies'} can be added to the next ${short} PDF.`,target:'otjmate',action:`Open ${mate}`})}if(settings.projects){const pending=projectList().find(p=>p.status==='complete'&&!p.completionSaved)||projectList().find(p=>p.quoteResult==='accepted'&&p.status!=='complete');if(pending)records.push({id:`project-action-${pending.id}-${pending.status}-${pending.completionSaved?'saved':'open'}`,icon:'⌂',title:pending.status==='complete'?'Save the finished ProjectMate job':'ProjectMate job ready to build',body:pending.title,target:'projectmate',value:pending.id,action:'Open project'})}if(settings.epa&&!COURSE.nvqUnits){const epa=epaReadinessStats(),attempted=[epa.knowledge,epa.discussion,epa.practical].filter(v=>v!==null).length;if(attempted&&epa.overall<70)records.push({id:`epa-practice-${COURSE.id}-${attempted}`,icon:'★',title:'Continue EPA practice',body:`EPA readiness is ${epa.overall}%. Complete or repeat the remaining practice areas.`,target:'epa',action:'Open EPA Academy'})}if(settings.learning){const progress=academyKnowledgeProgress(),entry=Object.entries(progress).find(([,value])=>value&&!value.complete&&Number(value.index)>=0);if(entry)records.push({id:`learning-in-progress-${entry[0]}`,icon:'▤',title:'Knowledge slides in progress',body:'Continue the teaching slides from where you stopped.',target:'knowledge-slides',action:'Continue learning'})}if(settings.certificates){const certs=Object.values(academyCertificates()).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||''))),latest=certs[0];if(latest)records.push({id:`certificate-${latest.id}`,icon:'◆',title:'Certificate available',body:`${latest.title} · ${latest.grade} · ${latest.percentage}%`,target:'certificates',action:'View certificate'})}return records}
function openLiveAppNotification(button){document.getElementById('notificationBellClose')?.click();const target=button.dataset.notificationTarget,value=button.dataset.notificationValue;if(target==='assignment'){state.assignment=Number(value);state.view='assignment'}else if(target==='progress'){state.view='home'}else if(target==='otjmate'){state.view='otjmate';state.otjMateTab='home'}else if(target==='projectmate'){state.view='projectmate';state.activeProjectId=value||null}else if(target==='epa')state.view='epa';else if(target==='knowledge-slides')state.view='knowledge-slides';else if(target==='certificates')state.view='certificates';render();window.scrollTo(0,0);if(target==='progress')setTimeout(showCourseProgress,40)}
function syncReminderNotifications(){const list=document.getElementById('notificationBellList');if(!list)return;list.querySelectorAll('[data-remindmate-notification],[data-live-app-notification]').forEach(x=>x.remove());const notificationSettings=appSettings().notifications,due=notificationSettings.enabled&&notificationSettings.reminders?reminders().filter(r=>!r.completed&&r.due<=isoToday()):[];let deleted=[];try{deleted=JSON.parse(localStorage.getItem('apprenticeplus.notifications.deleted.v1')||'[]')}catch{}for(const r of due){const notificationId=reminderNotificationId(r);if(deleted.includes(notificationId))continue;const item=document.createElement('article');item.className='notification-bell-item unread remindmate-notification';item.dataset.notificationId=notificationId;item.dataset.remindmateNotification='1';item.innerHTML=`<div class="notification-bell-item-content"><span class="notification-bell-item-icon" aria-hidden="true">✓</span><div><strong>${esc(r.due<isoToday()?'Overdue reminder':'Reminder due today')}</strong><p>${esc(r.title)}</p><small>${esc(r.details)}${r.recurrence!=='none'?` · Repeats ${esc(REMINDER_RECURRENCES[r.recurrence].toLowerCase())}`:''}</small><button type="button" class="notification-update-button" data-open-reminder="${r.id}">Open reminder</button></div></div>`;list.prepend(item)}for(const record of liveAppNotificationRecords(notificationSettings)){if(deleted.includes(record.id))continue;const item=document.createElement('article');item.className='notification-bell-item unread live-app-notification';item.dataset.notificationId=record.id;item.dataset.liveAppNotification='1';item.innerHTML=`<div class="notification-bell-item-content"><span class="notification-bell-item-icon" aria-hidden="true">${record.icon}</span><div><strong>${esc(record.title)}</strong><p>${esc(record.body)}</p><button type="button" class="notification-update-button" data-open-app-notification data-notification-target="${esc(record.target)}" data-notification-value="${esc(record.value||'')}">${esc(record.action)}</button></div></div>`;list.prepend(item)}list.querySelectorAll('[data-open-reminder]').forEach(b=>b.onclick=()=>{document.getElementById('notificationBellClose')?.click();state.view='remindmate';state.remindMateTab='home';render()});list.querySelectorAll('[data-open-app-notification]').forEach(b=>b.onclick=()=>openLiveAppNotification(b));window.dispatchEvent(new CustomEvent('apprenticeplus:notifications-refresh'));showDueReminderDeviceNotifications(due)}
function refreshAppNotifications(){try{syncActiveReviewMateProgress();syncReminderNotifications()}catch(error){console.warn('Notifications could not be refreshed',error)}}

function renderLearningSupport(){const tab=state.learningSupportTab||'home';const views={home:learningSupportHome,check:accessibilityCheckView,reading:readingToolsView,writing:writingToolsView,planner:plannerView,focus:focusView,hearing:hearingView,memory:memoryView,simple:explainSimplyView,settings:accessibilitySettingsView};const body=(views[tab]||learningSupportHome)();app.innerHTML=shell(`<button class="back no-print" id="backLearningSupport">← ${tab==='home'?'Toolbox':'Learning Support'}</button><div class="section-heading"><div><div class="number">Toolbox</div><h2>Learning Support</h2><p class="muted">Practical accessibility tools for reading, writing, focus, hearing and memory.</p></div></div>${tab==='home'?'':`<div class="support-tabs">${supportTabButton('home','Home')}${supportTabButton('reading','Reading')}${supportTabButton('writing','Writing')}${supportTabButton('planner','Planner')}${supportTabButton('settings','Settings')}</div>`}${body}`);document.getElementById('backLearningSupport').onclick=()=>{if(tab==='home'){state.view='resources'}else state.learningSupportTab='home';render();window.scrollTo(0,0)};document.querySelectorAll('[data-support-tab]').forEach(b=>b.onclick=()=>{state.learningSupportTab=b.dataset.supportTab;render();window.scrollTo(0,0)});bindLearningSupport(tab);}
function bindLearningSupport(tab){document.querySelectorAll('[data-a11y-setting]').forEach(el=>{el.oninput=()=>{const a=accessibilitySettings(),key=el.dataset.a11ySetting;a[key]=el.type==='checkbox'?el.checked:(el.type==='range'?Number(el.value):el.value);saveAccessibilitySettings(a);if(key==='fontSize')document.getElementById('fontSizeValue')?.replaceChildren(`${a.fontSize}%`);if(key==='lineSpacing')document.getElementById('lineSpacingValue')?.replaceChildren(String(a.lineSpacing));if(a.vibration&&navigator.vibrate)navigator.vibrate(20)}});const check=document.getElementById('saveAccessibilityCheck');if(check)check.onclick=()=>{const ans={};document.querySelectorAll('[data-a11y-check]').forEach(x=>ans[x.dataset.a11yCheck]=x.checked);localStorage.setItem(ACCESSIBILITY_CHECK_KEY,JSON.stringify(ans));const rec=recommendationsFor(ans),box=document.getElementById('supportRecommendations');box.innerHTML=`<div class="support-recommendations"><h4>Recommended tools</h4>${rec.length?rec.map(x=>`<span>✓ ${x}</span>`).join(''):'<p>No extra tools selected. You can still use any support feature.</p>'}</div>`};const txt=document.getElementById('supportWritingText');if(txt){const update=()=>{const value=txt.value.trim(),words=value?value.split(/\s+/).length:0,sentences=value?(value.match(/[.!?]+(?=\s|$)/g)||[]).length:0;document.getElementById('supportWordCount').textContent=words;document.getElementById('supportSentenceCount').textContent=sentences;document.getElementById('supportReadingTime').textContent=words?Math.max(1,Math.ceil(words/200)):0};txt.oninput=update;document.getElementById('clearSupportText').onclick=()=>{txt.value='';txt.dispatchEvent(new Event('input',{bubbles:true}))};document.getElementById('readSupportText').onclick=()=>{if(!txt.value.trim())return toast('Add some text first');if(!('speechSynthesis'in window))return toast('Read aloud is not supported on this device');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(txt.value);u.lang='en-GB';speechSynthesis.speak(u)}}const planner=document.getElementById('supportPlannerAssignment');if(planner)planner.onchange=()=>{state.assignment=Number(planner.value);renderLearningSupport()};const simple=document.getElementById('simpleAssignmentSelect');if(simple)simple.onchange=()=>{state.assignment=Number(simple.value);renderLearningSupport()};const focus=document.getElementById('toggleFocusMode');if(focus)focus.onclick=()=>{const a=accessibilitySettings();a.focusMode=!a.focusMode;saveAccessibilitySettings(a);renderLearningSupport()};const add=document.getElementById('addMemoryCard');if(add)add.onclick=()=>{const value=document.getElementById('memoryCardText').value.trim();if(!value)return toast('Write a reminder first');let cards=[];try{cards=JSON.parse(localStorage.getItem('apprenticeplus.memoryCards.v1')||'[]')}catch{}cards.unshift(value);localStorage.setItem('apprenticeplus.memoryCards.v1',JSON.stringify(cards.slice(0,30)));renderLearningSupport();toast('Reminder saved')};document.querySelectorAll('[data-remove-memory]').forEach(b=>b.onclick=()=>{let cards=[];try{cards=JSON.parse(localStorage.getItem('apprenticeplus.memoryCards.v1')||'[]')}catch{}cards.splice(Number(b.dataset.removeMemory),1);localStorage.setItem('apprenticeplus.memoryCards.v1',JSON.stringify(cards));renderLearningSupport()});const reset=document.getElementById('resetAccessibility');if(reset)reset.onclick=()=>{if(!confirm('Reset all accessibility settings on this device?'))return;localStorage.removeItem(ACCESSIBILITY_KEY);applyAccessibilitySettings();renderLearningSupport();toast('Accessibility settings reset')};enhanceVoiceToText(app)}

window.__apprenticePlusOpenNotificationSettings=()=>{state.view='settings';state.settingsTab='notifications';render();window.scrollTo(0,0)};

const FEEDBACK_EMAIL='apprentice-plus@outlook.com';
const FEEDBACK_DRAFT_KEY='apprenticeplus.feedbackmate.draft.v1';
function feedbackDraft(){try{return JSON.parse(localStorage.getItem(FEEDBACK_DRAFT_KEY)||'{}')}catch{return {}}}
function saveFeedbackDraft(){const form=document.getElementById('feedbackMateForm');if(!form)return;const draft={type:form.elements.type?.value||'Idea',name:form.elements.name?.value||'',email:form.elements.email?.value||'',subject:form.elements.subject?.value||'',message:form.elements.message?.value||''};try{localStorage.setItem(FEEDBACK_DRAFT_KEY,JSON.stringify(draft))}catch{}}
function feedbackDeviceInfo(){return `${navigator.userAgent||'Unknown device'} | Screen ${screen.width}×${screen.height} | Online: ${navigator.onLine?'Yes':'No'}`}
function renderFeedbackMate(){
 const d=feedbackDraft(),profileName=state.profile?.fullName||'';
 app.innerHTML=shell(`<button class="back no-print" id="backFeedbackMate">← Toolbox</button><div class="section-heading"><div><div class="number">Workplace app</div><h2>FeedbackMate</h2><p class="muted">Suggest an idea or report an issue directly to Apprentice+.</p></div></div><section class="card panel feedbackmate-card"><form id="feedbackMateForm"><div class="feedback-type-choice" role="group" aria-label="Submission type"><label><input type="radio" name="type" value="Idea" ${(d.type||'Idea')==='Idea'?'checked':''}><span>💡 Suggest an idea</span></label><label><input type="radio" name="type" value="Issue" ${d.type==='Issue'?'checked':''}><span>⚠️ Report an issue</span></label></div><div class="form-grid"><label class="field"><span>Name</span><input class="input" name="name" autocomplete="name" required value="${esc(d.name||profileName)}"></label><label class="field"><span>Email address</span><input class="input" name="email" type="email" autocomplete="email" required value="${esc(d.email||'')}"></label><label class="field full"><span>Short title</span><input class="input" name="subject" maxlength="100" required placeholder="What is your idea or issue?" value="${esc(d.subject||'')}"></label><label class="field full"><span>Details</span><textarea class="input" name="message" rows="7" maxlength="4000" required placeholder="Explain what you would like added, or what went wrong.">${esc(d.message||'')}</textarea><small>Do not include passwords or private evidence.</small></label><label class="field full feedback-screenshot-field"><span>Screenshot <em>optional</em></span><input class="input" id="feedbackScreenshot" name="attachment" type="file" accept="image/*"><small>A screenshot can help identify an issue. Maximum 8 MB.</small></label></div><div id="feedbackPreview" class="feedback-preview" hidden></div><div class="feedbackmate-meta"><strong>Automatically included for issue reports</strong><span>App version, current page, selected course, date and device details.</span></div><div class="btn-row feedbackmate-actions"><button class="btn secondary" type="button" id="clearFeedbackForm">Clear</button><button class="btn" type="submit" id="sendFeedback">Send</button></div><div id="feedbackStatus" class="feedback-status" role="status" aria-live="polite"></div></form></section><section class="accuracy-card"><strong>Replies</strong><p>Your email address is included as the reply-to address, so Apprentice+ can reply directly to you.</p></section>`);
 document.getElementById('backFeedbackMate').onclick=()=>{saveFeedbackDraft();state.view='resources';render()};
 const form=document.getElementById('feedbackMateForm'),file=document.getElementById('feedbackScreenshot'),preview=document.getElementById('feedbackPreview');
 form.querySelectorAll('input:not([type=file]),textarea').forEach(el=>el.addEventListener('input',saveFeedbackDraft));
 file.onchange=()=>{const f=file.files?.[0];preview.hidden=true;preview.innerHTML='';if(!f)return;if(f.size>8*1024*1024){file.value='';return toast('Screenshot must be smaller than 8 MB')}const url=URL.createObjectURL(f);preview.innerHTML=`<img src="${url}" alt="Selected screenshot"><span>${esc(f.name)}</span>`;preview.hidden=false};
 document.getElementById('clearFeedbackForm').onclick=()=>{if(!confirm('Clear this feedback form?'))return;localStorage.removeItem(FEEDBACK_DRAFT_KEY);renderFeedbackMate()};
 form.onsubmit=sendFeedbackMate;
}
async function sendFeedbackMate(event){
 event.preventDefault();const form=event.currentTarget,button=document.getElementById('sendFeedback'),status=document.getElementById('feedbackStatus');if(!form.reportValidity())return;
 const type=form.elements.type.value,name=form.elements.name.value.trim(),email=form.elements.email.value.trim(),subject=form.elements.subject.value.trim(),message=form.elements.message.value.trim(),attachment=form.elements.attachment.files?.[0];
 if(attachment&&attachment.size>8*1024*1024)return toast('Screenshot must be smaller than 8 MB');
 if(!navigator.onLine){status.className='feedback-status error';status.textContent='You are offline. Your form has been saved; reconnect and press Send again.';saveFeedbackDraft();return}
 button.disabled=true;button.textContent='Sending…';status.className='feedback-status sending';status.textContent='Sending your feedback securely…';
 const data=new FormData();data.append('_subject',`Apprentice+ ${type}: ${subject}`);data.append('_template','table');data.append('_captcha','false');data.append('Submission type',type);data.append('Name',name);data.append('email',email);data.append('Message',message);data.append('App version',APP_VERSION);data.append('Selected course',COURSE?.name||'Not available');data.append('Current page','FeedbackMate');data.append('Date and time',new Date().toLocaleString('en-GB'));data.append('Device details',feedbackDeviceInfo());if(attachment)data.append('attachment',attachment,attachment.name);
 try{const response=await fetch(`https://formsubmit.co/ajax/${encodeURIComponent(FEEDBACK_EMAIL)}`,{method:'POST',headers:{Accept:'application/json'},body:data});let result={};try{result=await response.json()}catch{}if(!response.ok||result.success===false)throw new Error(result.message||'Unable to send');localStorage.removeItem(FEEDBACK_DRAFT_KEY);status.className='feedback-status success';status.innerHTML='<strong>Feedback sent</strong><span>Your message has been submitted. A reply will be sent to your email address.</span>';form.reset();document.getElementById('feedbackPreview').hidden=true;toast('Feedback sent')}catch(error){saveFeedbackDraft();status.className='feedback-status error';status.innerHTML='<strong>Could not send automatically</strong><span>Your form is saved. Use the email fallback below or try again when connected.</span>';const fallback=document.createElement('a');fallback.className='btn secondary feedback-email-fallback';fallback.textContent='Open email app';fallback.href=`mailto:${FEEDBACK_EMAIL}?subject=${encodeURIComponent(`Apprentice+ ${type}: ${subject}`)}&body=${encodeURIComponent(`Name: ${name}\nReply email: ${email}\nType: ${type}\nApp version: ${APP_VERSION}\nCourse: ${COURSE?.name||'Not available'}\n\n${message}`)}`;status.appendChild(fallback)}finally{button.disabled=false;button.textContent='Send'}
}


