function courseKsbMap(){const map=new Map();for(const a of courseAssignments())for(const [code,text] of a.ksbs||[])if(!map.has(code))map.set(code,text);return map}
function projectKsbs(codes=[]){const map=courseKsbMap();return codes.filter(code=>map.has(code)).map(code=>({code,text:map.get(code)}))}
function difficultyLabel(value){return value==='easy'?'Easy · 1–2 hours':value==='hard'?'Hard · 4–6 hours':'Medium · 2–4 hours'}
function projectList(){return state.data[PROJECTMATE_KEY]||[]}
function saveProjects(list){state.data[PROJECTMATE_KEY]=list;return saveData()}
function projectById(id){return projectList().find(p=>p.id===id)}
function money(n){return new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(Number(n)||0)}
function randomBetween(a,b){return Math.round((a+Math.random()*(b-a))*100)/100}
function generatedProject(difficulty='medium'){const groups=PROJECT_TASKS[COURSE.id]||PROJECT_TASKS['property-maintenance-operative-st0171-v1-1'],pool=groups[difficulty]||groups.medium||Object.values(groups).flat(),t=pool[Math.floor(Math.random()*pool.length)],urgencies=['Flexible','Normal','Urgent'],urgency=urgencies[Math.floor(Math.random()*urgencies.length)],customerRate={Flexible:20,Normal:25,Urgent:30}[urgency],materials=t.materials.map(x=>({name:x[0],unit:x[1],price:x[2],target:x[3],suggested:x[3],qty:''})),materialCost=materials.reduce((sum,m)=>sum+Number(m.price)*Number(m.target),0),labour=Math.round(t.hours*customerRate*100)/100,overheads=Math.round(materialCost*.05*100)/100,baseline=materialCost*1.1+labour+overheads,budget=Math.round(Math.max(t.budget[1],baseline*({Flexible:1.08,Normal:1.12,Urgent:1.18}[urgency])));return {id:uid(),createdAt:Date.now(),status:'draft',source:'generated',difficulty,title:t.title,brief:t.brief,dimensions:t.dims,targetHours:t.hours,urgency,customerRate,budget,wastePercent:10,materials,labour,overheads,quoteResult:'',assignment:null,ksbs:projectKsbs(t.ksbs),elapsed:0,timerStarted:0,photos:[],completionNote:''}}
