 try{const media=await uniqueEvidenceMedia(result.blob,{kind:'video'});if(!media)return;const data=await blobToDataUrl(result.blob),thumbnail=await createVideoThumbnail(data),ext=mediaExtensionForMime(result.type,'video');d.files=d.files||[];d.files.push({name:`Supporting-video-${Date.now()}.${ext}`,evidenceName:'',type:result.type,size:result.size,mediaHash:media.hash,duration:result.duration,optimised:true,data,thumbnail});await commit(n,s,sd);analyticsEvent('supporting_evidence_files_added',{assignment_number:n,file_count:1,media_mode:'optimised_video',course_id:COURSE.id});renderSection();toast(`Optimised video autosaved · ${formatMediaSize(result.size)}`)}catch(error){console.error('Supporting video could not be saved',error);toast('The video could not be saved')}
