function monthlyPortfolioCard(){
 const d=portfolioDelta(),size=portfolioSizeEstimate(),last=d.status.uploadedAt?new Date(d.status.uploadedAt).toLocaleDateString('en-GB'):'Not yet',downloaded=!!d.status.downloadedAt&&!!d.status.pendingSnapshot,newItems=d.newEvidence.reduce((n,x)=>n+x.added,0),meter=Math.min(100,Math.max(0,size.totalBytes/PORTFOLIO_SAFE_TARGET_BYTES*100)),sizeMessage=size.tone==='over'?'Over Aptem’s 1 GB upload limit — remove or replace large original videos before exporting.':size.tone==='warning'?`Above the 900 MB safety target · ${formatMediaSize(Math.max(0,PORTFOLIO_UPLOAD_LIMIT_BYTES-size.totalBytes))} remains before 1 GB.`:`${formatMediaSize(size.remaining)} available before the 900 MB safety target.`,mate=learningHoursMateName(),short=learningHoursShortLabel(),criterion=COURSE.nvqUnits?'LOs':'KSBs';
 return `<section class="card panel entire-portfolio-card monthly-portfolio-card compact-monthly-card"><div class="monthly-portfolio-head"><div><div class="number">Monthly upload</div><h3>Complete course portfolio</h3></div><span class="monthly-last-upload">Last: ${esc(last)}</span></div><div class="monthly-portfolio-stats compact"><div><span>Evidence</span><strong>${newItems}</strong></div><div><span>${mate}</span><strong>${d.newOtjEntries.length} · ${d.otjHours.toFixed(1)} hrs</strong></div><div><span>${criterion}</span><strong>+${d.ksbGain}</strong></div><div><span>Academy</span><strong>${d.newAcademyTests.length} tests · ${d.newKnowledgeSlides.length} slides</strong></div><div><span>RPL</span><strong>${d.newRplUnits.length} units · ${d.newRplCriteria.length} criteria</strong></div><div><span>Full portfolio estimate</span><strong>${formatMediaSize(size.totalBytes)} / 900 MB</strong></div></div><div class="portfolio-size-panel ${size.tone}"><div><strong>Portfolio upload safety</strong><span>${size.percent}% of safety target</span></div><div class="portfolio-size-meter" role="progressbar" aria-label="Estimated complete portfolio size" aria-valuemin="0" aria-valuemax="900" aria-valuenow="${Math.min(900,Math.round(size.totalBytes/1_000_000))}"><span style="width:${meter}%"></span></div><small>${esc(sizeMessage)} App recordings are compressed; gallery videos retain their original size.</small></div><p class="monthly-portfolio-note">Every ZIP includes the complete course portfolio: all assignments, all saved evidence packs and media, full ${short} history, full Academy activity and the coursework restore file. NEW stamps and this summary identify only work added since the last confirmed upload.</p><div class="btn-row monthly-upload-actions"><button class="btn" id="downloadEntirePortfolio">${d.status.uploadedAt?'Download complete portfolio':'Download first complete portfolio'}</button>${downloaded?'<button class="btn secondary" id="openMonthlyPortfolio">Open portfolio</button><button class="btn" id="confirmMonthlyUpload">Uploaded online</button>':''}</div></section>`;
}
function wrapPdfText(ctx,text,maxWidth,font){ctx.font=font;const words=String(text||'').split(/\s+/),lines=[];let line='';for(const word of words){const test=line?`${line} ${word}`:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);return lines}
function monthlyEvidenceCode(name){const m=String(name||'').match(/(?:^|[^A-Z0-9])((?:K|S|B|LO)\s*\d+(?:\.\d+)?)(?:[^A-Z0-9]|$)/i);return m?m[1].replace(/\s+/g,'').toUpperCase():''}
function monthlyFileExtension(name,fallback='.bin'){const m=String(name||'').match(/(\.[a-z0-9]{2,5})$/i);return m?m[1].toLowerCase():fallback}
function monthlyAssignmentFolder(n){return `Assignment ${String(n).padStart(2,'0')}`}
function monthlyEvidenceFile(entry,assignmentNumber,counters){
 const original=String(entry.name||''),lower=original.toLowerCase(),code=monthlyEvidenceCode(original),codePart=code?` - ${code}`:'';
 let base='Evidence',label='Evidence file',fallback='.bin';
 if(lower.endsWith('.pdf')){base='Assignment';label='Assignment evidence PDF';fallback='.pdf'}
 else if(lower.includes('walkthrough')||lower.includes('ksb video')||/\.(mp4|mov|mkv)$/i.test(lower)){base='Video Walkthrough';label='Video walkthrough';fallback='.mp4'}
 else if(lower.includes('voice')||lower.includes('professional discussion')||lower.includes('audio')||/\.(m4a|mp3|wav|ogg)$/i.test(lower)){base='Professional Discussion';label='Professional discussion audio';fallback='.webm'}
 else if(/\.webm$/i.test(lower)){base='Video Walkthrough';label='Video walkthrough';fallback='.webm'}
 else if(/\.(mp4|webm|mov|mkv)$/i.test(lower)){base='Video';label='Supporting video';fallback='.mp4'}
 else if(/\.(png|jpe?g|webp)$/i.test(lower)){base='Photo';label='Photographic evidence';fallback='.jpg'}
 const key=`${assignmentNumber}:${base}${codePart}`,number=(counters[key]=(counters[key]||0)+1),needsNumber=base!=='Assignment'||number>1;
 const filename=`${base}${codePart}${needsNumber?` ${String(number).padStart(2,'0')}`:''}${monthlyFileExtension(original,fallback)}`;
 return {folder:monthlyAssignmentFolder(assignmentNumber),filename,path:`${monthlyAssignmentFolder(assignmentNumber)}/${filename}`,label,code,assignment:assignmentNumber,data:entry.data};
}
